import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"Setting Up API Keys","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/api-keys.md","filePath":"get-started/api-keys.md"}'),i={name:"get-started/api-keys.md"};function l(n,e,s,d,p,h){return a(),o("div",null,e[0]||(e[0]=[r(`<h1 id="setting-up-api-keys" tabindex="-1">Setting Up API Keys <a class="header-anchor" href="#setting-up-api-keys" aria-label="Permalink to &quot;Setting Up API Keys&quot;">​</a></h1><p>To use AI translation, you need API keys from one or more LLM providers.</p><h2 id="supported-providers" tabindex="-1">Supported Providers <a class="header-anchor" href="#supported-providers" aria-label="Permalink to &quot;Supported Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Models</th><th>Best For</th></tr></thead><tbody><tr><td><strong>OpenAI</strong></td><td>GPT-4o, GPT-4-turbo, GPT-3.5</td><td>General translation, fast responses</td></tr><tr><td><strong>Anthropic</strong></td><td>Claude 3.5 Sonnet, Claude 3 Opus</td><td>Complex texts, nuanced writing</td></tr><tr><td><strong>Google</strong></td><td>Gemini Pro, Gemini Ultra</td><td>Multilingual content</td></tr><tr><td><strong>Ollama</strong></td><td>Llama, Mistral, etc.</td><td>Free, offline, privacy</td></tr></tbody></table><h2 id="getting-api-keys" tabindex="-1">Getting API Keys <a class="header-anchor" href="#getting-api-keys" aria-label="Permalink to &quot;Getting API Keys&quot;">​</a></h2><h3 id="openai" tabindex="-1">OpenAI <a class="header-anchor" href="#openai" aria-label="Permalink to &quot;OpenAI&quot;">​</a></h3><ol><li>Go to <a href="https://platform.openai.com" target="_blank" rel="noreferrer">platform.openai.com</a></li><li>Sign up or log in</li><li>Navigate to <strong>API Keys</strong> in the sidebar</li><li>Click <strong>Create new secret key</strong></li><li>Copy the key (it won&#39;t be shown again!)</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>OpenAI requires a paid account with credits. New accounts may get free trial credits.</p></div><h3 id="anthropic" tabindex="-1">Anthropic <a class="header-anchor" href="#anthropic" aria-label="Permalink to &quot;Anthropic&quot;">​</a></h3><ol><li>Go to <a href="https://console.anthropic.com" target="_blank" rel="noreferrer">console.anthropic.com</a></li><li>Sign up or log in</li><li>Navigate to <strong>API Keys</strong></li><li>Click <strong>Create Key</strong></li><li>Copy the key</li></ol><h3 id="google-gemini" tabindex="-1">Google (Gemini) <a class="header-anchor" href="#google-gemini" aria-label="Permalink to &quot;Google (Gemini)&quot;">​</a></h3><ol><li>Go to <a href="https://makersuite.google.com" target="_blank" rel="noreferrer">makersuite.google.com</a></li><li>Sign in with your Google account</li><li>Click <strong>Get API key</strong></li><li>Create a key for a new or existing project</li><li>Copy the key</li></ol><h3 id="ollama-free-local" tabindex="-1">Ollama (Free, Local) <a class="header-anchor" href="#ollama-free-local" aria-label="Permalink to &quot;Ollama (Free, Local)&quot;">​</a></h3><p>Ollama runs models locally - no API key needed!</p><ol><li>Download from <a href="https://ollama.ai" target="_blank" rel="noreferrer">ollama.ai</a></li><li>Install and run Ollama</li><li>Download a model: <code>ollama pull llama2</code></li><li>Supervertaler will detect it automatically</li></ol><h2 id="adding-keys-to-supervertaler" tabindex="-1">Adding Keys to Supervertaler <a class="header-anchor" href="#adding-keys-to-supervertaler" aria-label="Permalink to &quot;Adding Keys to Supervertaler&quot;">​</a></h2><h3 id="method-1-settings-dialog-recommended" tabindex="-1">Method 1: Settings Dialog (Recommended) <a class="header-anchor" href="#method-1-settings-dialog-recommended" aria-label="Permalink to &quot;Method 1: Settings Dialog (Recommended)&quot;">​</a></h3><ol><li>Go to <strong>Settings</strong> tab</li><li>Find the <strong>LLM Settings</strong> section</li><li>Enter your API keys in the appropriate fields</li><li>Click <strong>Save</strong></li></ol><h3 id="method-2-api-keys-txt-file" tabindex="-1">Method 2: api_keys.txt File <a class="header-anchor" href="#method-2-api-keys-txt-file" aria-label="Permalink to &quot;Method 2: api_keys.txt File&quot;">​</a></h3><p>Create or edit <code>api_keys.txt</code> in the Supervertaler folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openai_api_key=sk-your-key-here</span></span>
<span class="line"><span>anthropic_api_key=sk-ant-your-key-here</span></span>
<span class="line"><span>google_api_key=AIza-your-key-here</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Security:</strong> The <code>api_keys.txt</code> file is gitignored and never uploaded to GitHub.</p></div><h2 id="testing-your-setup" tabindex="-1">Testing Your Setup <a class="header-anchor" href="#testing-your-setup" aria-label="Permalink to &quot;Testing Your Setup&quot;">​</a></h2><ol><li>Import a document or create a new project</li><li>Select a segment</li><li>Press <code>Ctrl+T</code> to translate</li><li>If successful, you&#39;ll see the translation appear</li></ol><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Solution</th></tr></thead><tbody><tr><td>&quot;Invalid API key&quot;</td><td>Double-check the key, ensure no extra spaces</td></tr><tr><td>&quot;Rate limit exceeded&quot;</td><td>Wait a minute, or upgrade your API plan</td></tr><tr><td>&quot;Model not found&quot;</td><td>Check if the model name is correct in settings</td></tr><tr><td>No response</td><td>Check your internet connection</td></tr></tbody></table><h2 id="choosing-a-provider" tabindex="-1">Choosing a Provider <a class="header-anchor" href="#choosing-a-provider" aria-label="Permalink to &quot;Choosing a Provider&quot;">​</a></h2><p><strong>For beginners:</strong> Start with OpenAI GPT-4o - it&#39;s fast, reliable, and has good translation quality.</p><p><strong>For cost-conscious users:</strong> Use Ollama with a local model like Llama 3 - completely free!</p><p><strong>For sensitive content:</strong> Use Ollama (data stays on your machine) or Anthropic Claude.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./first-project.html">Create your first translation project</a></li><li><a href="./../ai-translation/overview.html">Learn about AI translation options</a></li><li><a href="./../ai-translation/prompts.html">Set up custom prompts</a></li></ul>`,33)]))}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
